# Safe loop with watchdog limit
def safe_loop(target, max_iter=100):
    curr, iters = 0, 0
    while curr < target and iters < max_iter:
        curr += 1.5
        iters += 1
    return {'status': 'Terminated' if iters < max_iter else 'Timeout', 'iters': iters}
